impl<S: gx::Slots, T: gx::Coef> gx::Transform<Vector<S, T>> for Rotor<(), T> {
    type Output = Vector<S, T>;
    #[inline(always)]
    fn transform(self, x: Vector<S, T>) -> Vector<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 2>(&x.c) {
        let t0 = v[0] * v[0];
        let t2 = v[0] * v[1];
        let t3 = (-v[1]).mul_add(v[1], t0);
        let t5 = xv[1] * t2;
        let t6 = xv[0] * t2;
        let t7 = xv[1] * t3;
        let t8 = t5 * T::from_i64(2);
        let t9 = xv[0].mul_add(t3, t8);
        let t11 = (-t6).mul_add(T::from_i64(2), t7);
            return Vector { c: gx::slots::from_values::<S, T, 2>([t9, t11]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[0] * v[1];
        let m3 = (-v[1]).mul_add(v[1], m0);
        let m4 = m1 * T::from_i64(2);
        let m5 = -m4;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Vector { c: [(x[0].scale(m3) + x[1].scale(m4)).0, (x[0].scale(m5) + x[1].scale(m3)).0] }
    }
}

